<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import QuotationParticipants, { type Participant } from '../../components/QuotationParticipants.vue';
import { rupiah, rupiahInput } from '../../composables/costing';
import { postPdf } from '../../composables/pdf';
type Program = { id: number; nomor: string; judul: string; jenis: string; id_customer: string | null; harga_jual_peserta: string; target_peserta: number; closed_date: string | null; id_jenis_produk?: number; bep_harga: number };
type Detail = { kategori: string; teks: string };
type Quote = { id: number | null; nomor: string; status: string; id_penjualan: number | ''; tanggal: string; berlaku_sampai: string; id_sales: number | ''; sumber_info: string; tujuan: string; id_customer: string | null; kepada_nama: string | null; up_nama: string | null; alamat: string | null; kuota_peserta: number; harga_allin: string | number; diskon: string | number; biaya_lain: string | number; is_ppn: number | boolean; id_template_konfirmasi: number | ''; konfirmasi_isian: string[]; konfirmasi_pernyataan: string; kolom_peserta_b2b: string[]; keterangan: Detail[]; paket_maks_peserta?: number; tambahan_per_peserta?: string; dokumen_keterangan?: string | null };
type Template = { id: number; nama: string; id_jenis_produk: number | null; isian: string[]; pernyataan: string };
const props = defineProps<{ quotation: Quote; revisions: {revisi:number;created_date:string}[]; salesOrder: { id: number; nomor: string; revisi:number } | null; programs: Program[]; companies: { id_customer: string; name_customer: string; pic_name: string; address_office: string; kota: string }[]; sales: { id: number; nama: string }[]; templates: Template[]; fields: Record<string, string>; keteranganOptions: (Detail & { id: number; berlaku_untuk: string; is_default: number })[]; peserta: Participant[]; documents: { id: number; nama_file: string; ukuran_byte: number }[]; companyConfirmation: { id: number; nama_perusahaan: string; pic_nama: string; pic_jabatan: string; pic_hp: string; pic_email: string; surat_konfirmasi_nama: string; tgl_kirim: string } | null; link: string | null; linkClosed: string | null; calc: { grand_total: string; dpp: string; ppn: string; n_peserta: number } | null; can: { edit: boolean; cancel: boolean }; quotaOther: number }>();
const q = props.quotation;
const form = useForm({ ...q, harga_allin: Math.round(Number(q.harga_allin)), diskon: Math.round(Number(q.diskon)), biaya_lain: Math.round(Number(q.biaya_lain)), konfirmasi_isian: [...q.konfirmasi_isian], kolom_peserta_b2b: [...q.kolom_peserta_b2b], keterangan: q.keterangan.map((d) => ({ kategori: d.kategori, teks: d.teks })) });
const selected = computed(() => props.programs.find((p) => p.id === Number(form.id_penjualan)));
const b2b = computed(() => selected.value?.jenis === 'b2b');
const editable = q.status === 'draft' && props.can.edit;
const steps = ['Penawaran', 'Keterangan', 'Formulir Konfirmasi', 'Preview']; const step = ref(0);
const dataTab = ref(new URLSearchParams(window.location.search).get('tab') === 'data');
const error = ref(''); const busy = ref(false); const action = ref('');
function company() { const c = props.companies.find((c) => c.id_customer === form.id_customer); if (c) { form.up_nama = c.pic_name; form.alamat = [c.address_office, c.kota].filter(Boolean).join(', '); } }
function template() { const t = props.templates.find((t) => t.id === Number(form.id_template_konfirmasi)); if (t) { form.konfirmasi_isian = [...new Set(['nama', ...t.isian])]; form.konfirmasi_pernyataan = t.pernyataan; } }
function program() {
    if (q.id) return;
    form.tujuan = b2b.value ? 'company' : 'personal'; form.id_customer = selected.value?.id_customer ?? '';
    form.kuota_peserta = b2b.value ? 10 : 1; form.harga_allin = Math.round(Number(selected.value?.harga_jual_peserta ?? 0)) * Math.min(form.kuota_peserta, 25); company();
    form.keterangan = props.keteranganOptions.filter((d) => d.is_default && ['semua', selected.value?.jenis].includes(d.berlaku_untuk)).map((d) => ({ kategori: d.kategori, teks: d.teks }));
    const t = props.templates.find((t) => t.id_jenis_produk === selected.value?.id_jenis_produk) ?? props.templates[0];
    if (t) { form.id_template_konfirmasi = t.id; template(); }
    if (b2b.value) { form.konfirmasi_isian = ['nama']; form.konfirmasi_pernyataan = 'Telah membaca dan menyetujui syarat dan ketentuan yang berlaku di LabMania, termasuk ketentuan biaya peserta di atas 25 orang sesuai quotation.'; }
}
if (!q.id && form.id_penjualan) program();
watch(() => form.tanggal, (value, old) => { if (form.berlaku_sampai === `${old.slice(0, 4)}-12-31`) form.berlaku_sampai = `${value.slice(0, 4)}-12-31`; });
function save() { if (q.id) form.put(`/quotation/${q.id}`, { preserveState: 'errors' }); else form.post('/quotation', { preserveState: 'errors' }); }
async function preview() { busy.value = true; error.value = ''; try { await postPdf('/quotation/preview', form.data()); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
const transition = useForm({});
async function process() {
    if (action.value === 'batalkan') { transition.post(`/quotation/${q.id}/batalkan`, { preserveState: 'errors', onSuccess: () => { action.value = ''; } }); return; }
    busy.value = true; error.value = '';
    try { await postPdf(`/quotation/${q.id}/kirim`); action.value = ''; router.get(window.location.pathname, {}, { preserveState: false, preserveScroll: true, replace: true }); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; }
}
const quota = useForm({ kuota_peserta: q.kuota_peserta });
const deal = useForm({ peserta: props.peserta.filter((p) => p.status === 'menunggu').map((p) => p.id), dokumen: [] as File[], dokumen_keterangan: '' });
function files(e: Event) { deal.dokumen.push(...Array.from((e.target as HTMLInputElement).files ?? [])); (e.target as HTMLInputElement).value = ''; }
function saveDocuments() { deal.post(`/quotation/${q.id}/${q.status === 'deal' ? 'dokumen' : 'deal'}`, { forceFormData: true, preserveState: 'errors', onSuccess: () => { action.value = ''; deal.reset('dokumen'); } }); }
const sum = computed(() => {
    if (!editable && props.calc) return { count: props.calc.n_peserta, dpp: Number(props.calc.dpp), tax: Number(props.calc.ppn), total: Number(props.calc.grand_total) };
    const count = q.status === 'deal' ? (props.calc?.n_peserta ?? 0) : Number(form.kuota_peserta);
    const base = b2b.value ? rupiahInput(form.harga_allin) + Math.max(0, count - (q.paket_maks_peserta ?? 25)) * Number(q.tambahan_per_peserta ?? 300000) : count * Number(selected.value?.harga_jual_peserta ?? 0);
    const dpp = base - rupiahInput(form.diskon) * (b2b.value ? 1 : count); const tax = form.is_ppn ? Math.round(dpp * 11) / 100 : 0;
    return { count, dpp, tax, total: dpp + tax + rupiahInput(form.biaya_lain) };
});
function addKeterangan(d: Detail) { form.keterangan.push({ kategori: d.kategori, teks: d.teks }); }
const extra = ref('');
</script>
<template>
    <Head :title="q.nomor || 'Buat Quotation'" /><AppLayout title="Quotation">
        <div class="page-head"><h1>{{ q.nomor || 'Buat Quotation' }}</h1><span class="badge">{{ q.status }}</span></div>
        <p v-if="selected">{{ selected.nomor }} · {{ selected.judul }}{{ selected.closed_date ? ' · Closed' : '' }}</p>
        <p v-if="error" class="error" role="alert">{{ error }}</p><ul v-if="Object.keys(form.errors).length" class="error" role="alert"><li v-for="e in form.errors" :key="e">{{ e }}</li></ul>
        <nav v-if="q.id" class="form-actions" aria-label="Detail quotation"><button type="button" :aria-pressed="!dataTab" @click="dataTab = false">Detail Quotation</button><button type="button" :aria-pressed="dataTab" @click="dataTab = true">Data Peserta ({{ peserta.length }})</button></nav>
        <template v-if="dataTab"><section v-if="link" class="panel"><h2>Link Konfirmasi Kehadiran</h2><p>{{ linkClosed || 'Link terbuka' }}</p><a :href="link" target="_blank" rel="noopener noreferrer">{{ link }}</a><p class="muted">Bagikan link kepada calon peserta / PIC Company. Peserta hanya masuk melalui link ini.</p></section><div class="form-actions"><a :href="`/quotation/${q.id}/excel`">Unduh Excel</a><a v-if="peserta.some((p) => p.status !== 'batal')" :href="`/quotation/${q.id}/letters`" target="_blank" rel="noopener">Confirmation Letter (semua aktif)</a></div><section v-if="b2b" class="panel"><h2>Konfirmasi Company</h2><template v-if="companyConfirmation"><p>{{ companyConfirmation.nama_perusahaan }} ? {{ companyConfirmation.pic_nama }} ? {{ companyConfirmation.pic_jabatan }}</p><p>{{ companyConfirmation.pic_hp }} ? {{ companyConfirmation.pic_email }} ? {{ companyConfirmation.tgl_kirim }}</p><a :href="`/documents/company-confirmation/${companyConfirmation.id}?preview=1`" target="_blank" rel="noopener">Lihat {{ companyConfirmation.surat_konfirmasi_nama }}</a></template><p v-else>PIC Company belum mengirim daftar peserta.</p></section><QuotationParticipants :rows="peserta" :manage="can.edit" /></template>
        <template v-else>
            <nav v-if="editable" class="form-actions" aria-label="Langkah quotation"><button v-for="(s, i) in steps" :key="s" type="button" :aria-current="step === i ? 'step' : undefined" @click="step = i">{{ i + 1 }}. {{ s }}</button></nav>
            <form class="stack" novalidate @submit.prevent="save"><fieldset v-show="!editable || step === 0" :disabled="!editable || form.processing" class="panel"><legend>1. Penawaran</legend><div class="form-grid">
                <label>Penjualan Program Final<select v-model="form.id_penjualan" required :disabled="!!q.id" @change="program"><option value="">Pilih program</option><option v-for="p in programs" :key="p.id" :value="p.id">{{ p.nomor }} · {{ p.judul }}</option></select></label>
                <label>Tanggal quotation<input v-model="form.tanggal" type="date" required /></label><label>Berlaku sampai<input v-model="form.berlaku_sampai" type="date" :min="form.tanggal" required /></label>
                <label>Sales / marketing<select v-model="form.id_sales" required><option value="">Pilih sales aktif</option><option v-for="s in sales" :key="s.id" :value="s.id">{{ s.nama }}</option></select></label>
                <label>Sumber informasi<select v-model="form.sumber_info"><option v-for="s in ['Sales', 'Media sosial', 'Website', 'Referensi / repeat order', 'Lainnya']" :key="s">{{ s }}</option></select></label>
                <label>Quotation ke<select v-model="form.tujuan" :disabled="b2b"><option value="personal">Personal</option><option value="company">Company</option></select></label>
                <label v-if="form.tujuan === 'company'">Company<select v-model="form.id_customer" :disabled="b2b" required @change="company"><option value="">Pilih Company</option><option v-for="c in companies" :key="c.id_customer" :value="c.id_customer">{{ c.name_customer }}</option></select></label>
                <label v-else>Kepada<input v-model="form.kepada_nama" maxlength="100" required /></label><label v-if="form.tujuan === 'company'">u.p.<input v-model="form.up_nama" maxlength="100" /></label><label>Alamat<textarea v-model="form.alamat" maxlength="3000" rows="3"></textarea></label>
                <label>Kuota peserta<input v-model="form.kuota_peserta" type="number" :min="b2b ? 10 : 1" required /></label><label v-if="b2b">Harga paket s.d. {{ q.paket_maks_peserta ?? 25 }} peserta (Rp)<input v-model="form.harga_allin" inputmode="numeric" required /></label><p v-else>Harga / peserta: {{ rupiah(selected?.harga_jual_peserta) }}</p><label>{{ b2b ? 'Diskon paket' : 'Diskon per peserta' }} (Rp)<input v-model="form.diskon" inputmode="numeric" required /></label><label>Biaya lain-lain (Rp)<input v-model="form.biaya_lain" inputmode="numeric" required /></label><label><input v-model="form.is_ppn" type="checkbox" :true-value="1" :false-value="0" /> PPN 11%</label>
            </div><p v-if="selected">Target {{ selected.target_peserta }} · Kuota quotation lain {{ quotaOther }} · Sisa target {{ Math.max(0, selected.target_peserta - quotaOther - Number(form.kuota_peserta)) }}</p><p v-if="selected && sum.count > 0 && sum.dpp / sum.count < selected.bep_harga" class="notice">Harga setelah diskon {{ rupiah(sum.dpp / sum.count) }} / peserta di bawah BEP harga {{ rupiah(selected.bep_harga) }}. Quotation tetap dapat disimpan.</p><p v-if="b2b" class="notice">Paket tetap untuk peserta hingga {{ q.paket_maks_peserta ?? 25 }}. Peserta tambahan {{ rupiah(q.tambahan_per_peserta ?? 300000) }} / orang. B2B minimal 10 peserta.</p></fieldset>
            <fieldset v-show="!editable || step === 1" :disabled="!editable || form.processing" class="panel"><legend>2. Keterangan</legend><details v-if="editable"><summary>Tambah dari Template Keterangan</summary><button v-for="d in keteranganOptions.filter((d) => ['semua', selected?.jenis].includes(d.berlaku_untuk))" :key="d.id" type="button" @click="addKeterangan(d)">{{ d.kategori }}: {{ d.teks }}</button></details><div v-for="(d, i) in form.keterangan" :key="i" class="form-grid"><label>Kategori<select v-model="d.kategori"><option v-for="k in ['syarat', 'termasuk', 'tidak', 'dokumen', 'klausul']" :key="k">{{ k }}</option></select></label><label>Teks<textarea v-model="d.teks" :readonly="d.kategori === 'klausul'" maxlength="2000" rows="3" required></textarea></label><button v-if="editable" type="button" class="danger" @click="form.keterangan.splice(i, 1)">Hapus</button></div><button v-if="editable" type="button" @click="addKeterangan({ kategori: 'syarat', teks: '' })">Tambah keterangan</button><p v-if="!form.keterangan.length" class="muted">Belum ada keterangan.</p></fieldset>
            <fieldset v-show="!editable || step === 2" :disabled="!editable || form.processing" class="panel"><legend>3. Formulir Konfirmasi</legend><template v-if="!b2b"><label>Template aktif<select v-model="form.id_template_konfirmasi" required @change="template"><option value="">Pilih template</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.nama }}</option></select></label><div class="form-grid"><label v-for="(label, key) in fields" :key="key"><input v-model="form.konfirmasi_isian" type="checkbox" :value="key" :disabled="key === 'nama'" /> {{ label }}</label></div><label>Isian tambahan<input v-model="extra" maxlength="80" /></label><button v-if="editable" type="button" @click="extra.trim() && form.konfirmasi_isian.push(extra.trim()); extra = ''">Tambah isian</button><p v-for="x in form.konfirmasi_isian.filter((x) => !fields[x])" :key="x">{{ x }} <button v-if="editable" type="button" @click="form.konfirmasi_isian = form.konfirmasi_isian.filter((f) => f !== x)">Hapus</button></p></template><template v-else><p>Konfirmasi satu kali oleh PIC Company. Nama peserta wajib.</p><label v-for="k in ['jabatan', 'email', 'wa', 'nik']" :key="k"><input v-model="form.kolom_peserta_b2b" type="checkbox" :value="k" /> {{ fields[k] }}</label></template><label>Pernyataan persetujuan<textarea v-model="form.konfirmasi_pernyataan" rows="4" maxlength="2000" required></textarea></label></fieldset>
            <section v-show="!editable || step === 3" class="panel"><h2>4. Preview</h2><p>{{ sum.count }} peserta · DPP {{ rupiah(sum.dpp) }} · PPN {{ rupiah(sum.tax) }} · Total {{ rupiah(sum.total) }}</p><p class="muted">Nilai sebelum Deal berdasarkan kuota. Nilai Deal berdasarkan peserta terpilih. Server menghitung ulang nilai resmi.</p><button v-if="editable" type="button" :disabled="busy" @click="preview">{{ busy ? 'Menyiapkan PDF…' : 'Preview PDF sebelum simpan' }}</button><a v-else :href="`/quotation/${q.id}/pdf`" target="_blank" rel="noopener">Cetak ulang PDF</a></section>
            <div class="form-actions"><button v-if="editable && step > 0" type="button" @click="step--">Sebelumnya</button><button v-if="editable && step < 3" type="button" @click="step++">Berikutnya</button><button v-if="editable && step === 3" class="primary" :disabled="form.processing">{{ form.processing ? 'Menyimpan…' : 'Simpan Draft' }}</button><button v-if="q.id && q.status === 'draft' && can.edit" type="button" @click="action = 'kirim'">Kirim dan Cetak Quotation</button><button v-if="q.status === 'terkirim' && can.edit" type="button" @click="action = 'deal'">Deal</button><button v-if="['draft', 'terkirim'].includes(q.status) && can.cancel" type="button" class="danger" @click="action = 'batalkan'">Batalkan</button><Link :href="form.id_penjualan ? `/quotation/batch/${form.id_penjualan}` : '/quotation'">Kembali</Link></div></form>
            <form v-if="q.status === 'terkirim' && !b2b && q.tujuan === 'company' && can.edit" class="panel" @submit.prevent="quota.post(`/quotation/${q.id}/kuota`, { preserveState: 'errors' })"><h2>Tambah kuota Company yang sama</h2><label>Kuota baru<input v-model="quota.kuota_peserta" type="number" :min="Number(q.kuota_peserta) + 1" required /></label><p v-for="e in quota.errors" :key="e" class="error" role="alert">{{ e }}</p><button :disabled="quota.processing">Tambah kuota</button></form>
            <section v-if="q.status === 'deal'" class="panel"><h2>Sales Order</h2><Link v-if="salesOrder && (($page.props.permissions as Record<string, string[]>).sales_order || []).includes('View')" :href="`/sales-order/${salesOrder.id}`">Lihat Sales Order {{ salesOrder.nomor + (salesOrder.revisi ? `-rev${salesOrder.revisi}` : '') }}</Link><p v-else-if="salesOrder">{{ salesOrder.nomor + (salesOrder.revisi ? `-rev${salesOrder.revisi}` : '') }}</p><h2>Dokumen Deal</h2><p>{{ q.dokumen_keterangan }}</p><p v-for="d in documents" :key="d.id"><a :href="`/documents/quotation/${d.id}`" target="_blank" rel="noopener">{{ d.nama_file }}</a> ({{ Math.ceil(d.ukuran_byte / 1024) }} KB)</p><button v-if="can.edit" type="button" @click="action = 'dokumen'">Tambah dokumen customer</button></section>
        </template>
        <section v-if="q.id && revisions.length" class="panel"><h2>Riwayat revisi Quotation</h2><p v-for="r in revisions" :key="r.revisi"><a :href="`/quotation/${q.id}/revisi/${r.revisi}/quotation`" target="_blank" rel="noopener">Versi {{ r.revisi || 'awal' }}</a> {{ r.created_date }}</p></section><ConfirmDialog v-if="['kirim', 'batalkan'].includes(action)" :title="action === 'kirim' ? 'Kirim dan Cetak Quotation?' : 'Batalkan Quotation?'" :confirm-label="action === 'kirim' ? 'Kirim dan Cetak' : 'Batalkan'" :busy="busy || transition.processing" @cancel="action = ''" @confirm="process"><p>{{ action === 'kirim' ? 'Draft terkunci setelah dikirim. PDF berisi Penawaran serta Syarat & Ketentuan.' : 'Quotation dan seluruh peserta menjadi Batal. Link ditutup.' }}</p><p v-for="e in transition.errors" :key="e" class="error" role="alert">{{ e }}</p><p v-if="error" class="error" role="alert">{{ error }}</p></ConfirmDialog>
        <ConfirmDialog v-if="['deal', 'dokumen'].includes(action)" :title="action === 'deal' ? 'Tandai Deal' : 'Tambah dokumen customer'" :confirm-label="action === 'deal' ? 'Simpan Deal' : 'Simpan dokumen'" :busy="deal.processing" @cancel="action = ''" @confirm="saveDocuments"><template v-if="action === 'deal'"><p>Peserta tidak dicentang menjadi Batal. Deal membuat Master Peserta, satu SO, dan Surat Tugas pertama program.</p><label v-for="p in peserta.filter((p) => p.status === 'menunggu')" :key="p.id"><input v-model="deal.peserta" type="checkbox" :value="p.id" :disabled="!!p.konfirmasi_ulang && !p.konfirmasi_ulang.diproses_date" /> {{ p.nama }} · {{ p.instansi }}</label><p v-if="!peserta.some((p) => p.status === 'menunggu')" class="notice">Belum ada peserta Menunggu. Bagikan link terlebih dahulu.</p></template><label>Keterangan dokumen<input v-model="deal.dokumen_keterangan" maxlength="200" /></label><label>Dokumen customer (wajib, maksimal 5 MB / berkas)<input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" @change="files" /></label><ul><li v-for="(f, i) in deal.dokumen" :key="i">{{ f.name }} ({{ Math.ceil(f.size / 1024) }} KB) <button type="button" @click="deal.dokumen.splice(i, 1)">Hapus</button></li></ul><p v-for="e in deal.errors" :key="e" class="error" role="alert">{{ e }}</p><progress v-if="deal.progress" :value="deal.progress.percentage" max="100" aria-label="Progres unggahan"></progress></ConfirmDialog>
    </AppLayout>
</template>


